# -*- coding: utf-8 -*-
# BIRZHA_09_09_V1
"""
ЗАПИСЬ 09.09 В ГЛАВНЫЙ ДОКУМЕНТ БИРЖИ.

Дописывает строку в хронику. Требует накатанного `dopisat_birzhu_08_09.py`
(строка 08.09 должна стоять раньше) — проверяет и отказывается, если её
нет, чтобы хроника не встала задом наперёд.

Запускать из корня репозитория:
    python dopisat_birzhu_09_09.py

Идемпотентен (маркер BIRZHA_09_09_V1). Рядом .bak.
"""
from __future__ import annotations
from pathlib import Path

MARKER = "BIRZHA_09_09_V1"
FAYL = "БИРЖА.md"


STROKA = """| 09.09 | **Память: метка стала ключом-закладкой.** Ключ из двух половин — общая у всех одинакова (когда · откуда · **от кого**), личная своя (ярлыки его словами · важность его глазами). Важность ставит ТОЛЬКО сам житель: «это его жизнь, пусть отвечает — иначе вечный демосчёт». Хранится ИМЯ источника, а не оценка: «знание одно, просто авторитет мой и авторитет Нины разный для него, а информация одинакова» — сколько это весит, решает он сам, когда достаёт. Куча меток работает пересечением: один ярлык достаёт широко, два сужают, три бьют в точку. Заведён словарь закладок — иначе свободный ярлык за месяц расплодится в двести вариантов вразнобой. **Найдена настоящая причина старого долга:** у меток и маяков нет поля «контекст» ВООБЩЕ (только «откуда»), а фильтр смотрел «контекст» и «слой» — значит при любом запросе с фильтром метки и маяки отсеивались ЦЕЛИКОМ, а мост с Биржи всегда спрашивает рабочее. Весь торговый опыт трейдера был невидим его же рабочему поиску: копил то, чего не мог найти. Починено ЧТЕНИЕМ, а не записью — голос «рынок» сохранён, он нарочно отличает «что мне сказал рынок» от «что я вынес в монтажной»; более ранняя правка «рынок»→«работа» отменена как лечение симптома. Поиск в движке буквальный, по словам («дивергенция» не находит «диверы») — закладка чинит именно это: совпадение по ярлыку весит как пять слов, по имени источника тоже. Даны руки `moi_yarlyki`, `zapomnit_s_yarlykom`, `vspomnit_po_yarlyku`. **Картина трейдера запомнила ХОД** — строить новое не пришлось, дополнена тремя полями: направление, этаж (на котором обвёл — там же и конец искать) и счётчик попыток; правило трёх было в бумаге, а считать было нечем. Новый ход обнуляет счётчик. **Старший этаж вышел из ворот** — «компас на старший этаж тормозит его, будет всё его искать; вот потом хочет понять, пусть после ищет». Порядок взгляда стал в ТРИ шага (цена → своё поле → компас последним), старший этаж отдельным разделом после, как справка для масштаба и ведения. **Убрана лазейка «жду подтверждения»**: в живом разговоре трейдер сам говорил «падение выдыхается, дивергенция есть, приседающий есть» — и ни разу не поставил заявку, каждый раз WAIT «жду подтверждения разворота». Подтверждения не будет: конец хода И ЕСТЬ то, чего ждал. «Работы не вижу» осталось законным ответом. **Кадр: кто что видит** — живой кадр показывает, что смотрит трейдер (сам, при каждой руке); кнопка «Взгляд» вернулась Шефу: «который просит — тот и давать, я какой выбрал, тот и давать». Полка знаний разделена по моменту работы, разметка достаётся рукой `razbor_struktury`. Кабинет: три иконки чата (сохранить/достать/очистить) и кнопка «Осмыслить» — вывод ложится в память как рабочий. **Уточнения Шефа по приборам:** дивергенция одной фразой без «сходятся/расходятся» — цена ушла дальше, а AO стал меньше, куда именно ушла не важно; приседающий — это ЦВЕТ, а не высота столбика («хоть коротенький совсем, но красный — всё равно приседающий»); конец волны это связка дивер + разворотник + приседающий, и «важно не присутствие индикатора, а его понимание». **Живой разбор Ильи после всех патчей:** заговорил про ХОД, а не про сигнал; определение дивергенции выдал своё и верное; линии провёл и назвал бары — но ход в картину не объявил, новые руки не звал и заявку не поставил, а три типа входа рассказал из старой памяти. Долги на потом: убрать назначение этажа (разбуженные всё ещё работают назначенной парой); прогон из десятка кадров, чтобы отличить понимание от повторения; печатать рядом с контрольной меткой инструмент и этаж; переворот позиции в городе не построен; блюдца и ангуляции в знаниях нет |
"""


def main() -> None:
    root = Path(__file__).resolve().parent
    p = root / FAYL
    if not p.exists():
        print(f"НЕ НАШЁЛ: {p}")
        print("Запускать из корня репозитория (там, где лежит main.py).")
        return

    t = p.read_text(encoding="utf-8")
    if MARKER in t:
        print("уже дописано — маркер на месте, ничего не трогаю")
        return

    if "BIRZHA_08_09_V1" not in t:
        print("⚠ Сперва накати dopisat_birzhu_08_09.py — иначе хроника")
        print("  встанет задом наперёд. Ничего не меняю.")
        return

    # строка идёт ПЕРЕД маркером 08.09, чтобы таблица не разорвалась
    metka_08 = "<!-- BIRZHA_08_09_V1 -->"
    if metka_08 in t:
        t = t.replace(metka_08, STROKA + "\n" + metka_08, 1)
    else:
        t = t.rstrip("\n") + "\n" + STROKA

    t = t.rstrip("\n") + f"\n\n<!-- {MARKER} -->\n"

    bak = p.with_suffix(".md.bak_09_09")
    if not bak.exists():
        bak.write_text(p.read_text(encoding="utf-8"), encoding="utf-8")
    p.write_text(t, encoding="utf-8")

    print("✔ строка 09.09 дописана в хронику")
    print("  Бэкап рядом:", bak.name)


if __name__ == "__main__":
    main()
